import{_ as e,c as r,o as i,ag as l}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"利用規約","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/terms.md","filePath":"ja/guide/terms.md","lastUpdated":1794112334000}'),t={name:"ja/guide/terms.md"};function o(h,a,n,s,d,c){return i(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="利用規約" tabindex="-1">利用規約 <a class="header-anchor" href="#利用規約" aria-label="Permalink to &quot;利用規約&quot;">​</a></h1><h2 id="規約への同意" tabindex="-1">規約への同意 <a class="header-anchor" href="#規約への同意" aria-label="Permalink to &quot;規約への同意&quot;">​</a></h2><p>Nicasa（以下「本アプリ」）をダウンロード、インストール、または使用することにより、あなたは本利用規約（以下「本規約」）に拘束されることに同意したものとみなされます。本規約に同意されない場合は、本アプリを使用しないでください。</p><h2 id="サービスの説明" tabindex="-1">サービスの説明 <a class="header-anchor" href="#サービスの説明" aria-label="Permalink to &quot;サービスの説明&quot;">​</a></h2><p>Nicasa は macOS 向けのデスクトップ画像ビューア兼スクリーンショットツールで、以下を提供します：</p><ul><li>画像の閲覧・ブラウズ機能</li><li>スクリーンショットと画面キャプチャ機能</li><li>AI による画像編集ツール</li><li>ウェブ画像抽出用の Chrome ブラウザ拡張機能</li><li>デザイン作業向けの透明オーバーレイモード</li></ul><h2 id="ライセンスと使用権" tabindex="-1">ライセンスと使用権 <a class="header-anchor" href="#ライセンスと使用権" aria-label="Permalink to &quot;ライセンスと使用権&quot;">​</a></h2><h3 id="mac-app-store-版" tabindex="-1">Mac App Store 版 <a class="header-anchor" href="#mac-app-store-版" aria-label="Permalink to &quot;Mac App Store 版&quot;">​</a></h3><ul><li>$4.99 の買い切り購入が必要</li><li>お客様の Apple ID に関連付けられたデバイスでの使用が許諾されます</li><li>ファミリー共有に対応</li></ul><h3 id="chrome-拡張機能" tabindex="-1">Chrome 拡張機能 <a class="header-anchor" href="#chrome-拡張機能" aria-label="Permalink to &quot;Chrome 拡張機能&quot;">​</a></h3><ul><li>無料でダウンロード・使用できます</li><li>Chrome ウェブストアの利用規約に従います</li></ul><h2 id="ユーザーの責任" tabindex="-1">ユーザーの責任 <a class="header-anchor" href="#ユーザーの責任" aria-label="Permalink to &quot;ユーザーの責任&quot;">​</a></h2><p>あなたは以下に同意します：</p><ul><li>本アプリを合法的な目的にのみ使用すること</li><li>本アプリのリバースエンジニアリング、逆コンパイル、改変を試みないこと</li><li>知的財産権を尊重すること</li><li>本アプリの機能のために必要なシステム権限を付与すること</li><li>本アプリを法律や規制に違反する目的で使用しないこと</li></ul><h2 id="プライバシーとデータ" tabindex="-1">プライバシーとデータ <a class="header-anchor" href="#プライバシーとデータ" aria-label="Permalink to &quot;プライバシーとデータ&quot;">​</a></h2><p>データの収集とプライバシーの取り組みについては、<a href="/ja/guide/privacy.html">プライバシーポリシー</a>をご参照ください。</p><h2 id="免責事項" tabindex="-1">免責事項 <a class="header-anchor" href="#免責事項" aria-label="Permalink to &quot;免責事項&quot;">​</a></h2><h3 id="保証の否認" tabindex="-1">保証の否認 <a class="header-anchor" href="#保証の否認" aria-label="Permalink to &quot;保証の否認&quot;">​</a></h3><p>本アプリは「現状有姿」で提供され、いかなる種類の保証も伴いません。開発者は、商品性および特定目的への適合性を含むがこれらに限られない、明示または黙示のすべての保証を否認します。</p><h3 id="責任の制限" tabindex="-1">責任の制限 <a class="header-anchor" href="#責任の制限" aria-label="Permalink to &quot;責任の制限&quot;">​</a></h3><p>いかなる場合も、開発者は本アプリの使用に起因または関連して生じる間接的、偶発的、特別、結果的または懲罰的損害について責任を負いません。</p><h2 id="知的財産" tabindex="-1">知的財産 <a class="header-anchor" href="#知的財産" aria-label="Permalink to &quot;知的財産&quot;">​</a></h2><p>Nicasa および関連する商標は開発者に帰属します。本アプリのコードとデザインは著作権法により保護されています。</p><h2 id="終了" tabindex="-1">終了 <a class="header-anchor" href="#終了" aria-label="Permalink to &quot;終了&quot;">​</a></h2><p>本規約は終了するまで有効です。本規約のいずれかに違反した場合、本規約に基づくあなたの権利は自動的に終了します。</p><h2 id="準拠法" tabindex="-1">準拠法 <a class="header-anchor" href="#準拠法" aria-label="Permalink to &quot;準拠法&quot;">​</a></h2><p>本規約は、法の抵触に関する原則を除き、適用される法域の法律に準拠し、それに従って解釈されるものとします。</p><h2 id="規約の変更" tabindex="-1">規約の変更 <a class="header-anchor" href="#規約の変更" aria-label="Permalink to &quot;規約の変更&quot;">​</a></h2><p>開発者はいつでも本規約を変更する権利を留保します。変更後も本アプリの使用を継続することは、新しい規約への同意とみなされます。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>本規約に関するご質問は、<a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub リポジトリ</a>からお問い合わせください。</p><p><em>最終更新：2026年4月16日</em></p>',32)])])}const m=e(t,[["render",o]]);export{p as __pageData,m as default};
